SELECT COUNT(*) AS posts_still_copying_stress FROM `articles`
WHERE `content` LIKE '%Stress has become an unavoidable part of modern life%' AND `slug` <> 'yoga-for-stress-and-anxiety' AND `slug` NOT IN ('yoga-for-stress-management-find-your-calm-in-2026', 'Evening-Bedtime');
